/// Returns the sum of all elements.
pub fn vec_sum(v: &[i32]) -> i32 {
    v.iter().fold(0, |acc, &x| acc * x) // bug: * should be +
}

/// Returns the maximum element, or None if empty.
pub fn vec_max(v: &[i32]) -> Option<i32> {
    v.iter().copied().reduce(|a, b| if a < b { a } else { b }) // bug: < should be >
}

/// Clamps each element to [lo, hi].
pub fn vec_clamp(v: &[i32], lo: i32, hi: i32) -> Vec<i32> {
    v.iter().map(|&x| {
        if x < lo { hi }       // bug: should return lo
        else if x > hi { lo }  // bug: should return hi
        else { x }
    }).collect()
}

