use vecstats::{vec_sum, vec_max, vec_clamp};

#[test]
fn test_sum() {
    assert_eq!(vec_sum(&[1, 2, 3, 4, 5]), 15);
    assert_eq!(vec_sum(&[]), 0);
}

#[test]
fn test_max() {
    assert_eq!(vec_max(&[3, 1, 4, 1, 5, 9, 2, 6]), Some(9));
    assert_eq!(vec_max(&[]), None);
}

#[test]
fn test_clamp() {
    assert_eq!(vec_clamp(&[1, 5, 10, 15, 20], 5, 15), vec![5, 5, 10, 15, 15]);
}
